"""Currency conversion utilities for cross-border auction bids."""

from decimal import Decimal, ROUND_HALF_UP


class UnsupportedCurrencyError(Exception):
    pass


_EXCHANGE_RATES = {
    ("USD", "USD"): Decimal("1"),
    ("EUR", "USD"): Decimal("1.08"),
    ("USD", "EUR"): Decimal("0.93"),
    ("GBP", "USD"): Decimal("1.27"),
    ("USD", "GBP"): Decimal("0.79"),
    ("EUR", "EUR"): Decimal("1"),
    ("GBP", "GBP"): Decimal("1"),
    ("JPY", "USD"): Decimal("0.0067"),
    ("USD", "JPY"): Decimal("149.20"),
}


def convert_to_base(amount, from_currency, to_currency):
    """Convert a proposed bid amount into the auction's base currency."""
    if amount <= 0:
        raise ValueError("bid amount must be positive")

    key = (from_currency.upper(), to_currency.upper())
    try:
        rate = _EXCHANGE_RATES[key]
    except KeyError:
        raise UnsupportedCurrencyError(
            f"no exchange rate available for {from_currency} -> {to_currency}"
        )

    converted = (amount * rate).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    return converted


def format_amount(amount, currency_code):
    return f"{amount:.2f} {currency_code.upper()}"

"""Business-rule checks applied before a bid is accepted."""

from decimal import Decimal

import currency


class AuctionClosedError(Exception):
    pass


class BidTooLowError(Exception):
    pass


class BidRejectedError(Exception):
    pass


MAX_JUMP_MULTIPLIER = Decimal("25")


def validate_bid(auction, bidder, amount, currency_code):
    """Check that a proposed bid can legally be accepted, normalized to the auction's currency."""
    if auction.closed:
        raise AuctionClosedError(f"auction {auction.id} is no longer accepting bids")

    if bidder.id == auction.seller_id:
        raise BidRejectedError("sellers may not bid on their own listings")

    amount_base = currency.convert_to_base(amount, currency_code, auction.currency)

    min_next_bid = auction.current_price + auction.min_increment
    if amount_base < min_next_bid:
        raise BidTooLowError(
            f"bid of {currency.format_amount(amount_base, auction.currency)} is below "
            f"the minimum next bid of {currency.format_amount(min_next_bid, auction.currency)}"
        )

    if auction.current_price > 0 and amount_base > auction.current_price * MAX_JUMP_MULTIPLIER:
        raise BidRejectedError(
            f"bid of {currency.format_amount(amount_base, auction.currency)} is implausibly "
            f"far above the current price and has been flagged for manual review"
        )

    return amount_base

"""Bid ledger: places funding holds and records winning bid history."""

import random

import currency


class InsufficientFundsError(Exception):
    pass


class GatewayTimeoutError(Exception):
    pass


class Hold:
    def __init__(self, account_id, amount, confirmed):
        self.account_id = account_id
        self.amount = amount
        self.confirmed = confirmed


class PaymentGateway:
    """Stand-in for the real payment processor's hold API."""

    def __init__(self, failure_rate=0.0):
        self._failure_rate = failure_rate

    def authorize_hold(self, account_id, amount, available_balance):
        if amount > available_balance:
            raise InsufficientFundsError(
                f"account {account_id} has insufficient balance to cover {amount}"
            )
        if random.random() < self._failure_rate:
            raise GatewayTimeoutError(
                f"payment processor did not respond in time for account {account_id}"
            )
        return Hold(account_id, amount, confirmed=True)


_gateway = PaymentGateway(failure_rate=0.05)

_bid_history = []


def commit_bid(auction, bidder, amount_base):
    """Reserve the bidder's funds and, once secured, record the bid as the new leading offer."""
    hold = _reserve_funds(bidder, amount_base)

    auction.current_price = amount_base
    auction.leading_bidder_id = bidder.id

    entry = {
        "auction_id": auction.id,
        "bidder_id": bidder.id,
        "amount": amount_base,
        "amount_display": currency.format_amount(amount_base, auction.currency),
        "hold_confirmed": hold.confirmed,
    }
    _bid_history.append(entry)
    return entry


def _reserve_funds(bidder, amount_base):
    try:
        hold = _gateway.authorize_hold(bidder.id, amount_base, bidder.available_balance)
    except InsufficientFundsError:
        raise
    except Exception:
        hold = Hold(bidder.id, amount_base, confirmed=False)
    return hold


def bid_history_for(auction_id):
    return [entry for entry in _bid_history if entry["auction_id"] == auction_id]
